// src/components/SelectedSidebar.js
import React from 'react';
import styled from 'styled-components';

const SidebarContainer = styled.div`
  position: sticky;
  top: 20px;
  width: 300px;
  background-color: #fff;
  border: 1px solid #ddd;
  border-radius: 5px;
  padding: 15px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const Item = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 10px 0;
  padding: 10px;
  background-color: #f1f5f9;
  border: 1px solid #ddd;
  border-radius: 5px;
`;

const RemoveButton = styled.button`
  background-color: red;
  color: white;
  border: none;
  padding: 5px 10px;
  border-radius: 3px;
  cursor: pointer;

  &:hover {
    background-color: darkred;
  }
`;

const TotalPrice = styled.div`
  margin-top: 15px;
  font-weight: bold;
  font-size: 1.2rem;
  text-align: center;
`;

const Recommendation = styled.div`
  margin-top: 15px;
  background-color: #e9f5ff;
  padding: 10px;
  border-radius: 5px;
  border: 1px solid #b0e0e6;
`;

const CheckoutButton = styled.button`
  background-color: green;
  color: white;
  width: 100%;
  padding: 10px;
  border-radius: 5px;
  font-size: 1rem;
  cursor: pointer;
  margin-top: 10px;

  &:hover {
    background-color: darkgreen;
  }
`;

const SelectedSidebar = ({ selectedItems, removeItem, onCheckout }) => {
  // Calculate total price
  const totalPrice = selectedItems.reduce((total, item) => {
    const itemPrice = parseFloat(item.price.replace('$', ''));
    return total + itemPrice;
  }, 0);

  // Example recommendations based on selected items
  const getRecommendations = () => {
    if (selectedItems.some((item) => item.category === 'bike')) {
      return 'You selected a bike. Don’t forget to add a helmet and water bottle!';
    } else if (selectedItems.some((item) => item.category === 'wetsuit')) {
      return 'Got a wetsuit? Consider a swimming cap and goggles!';
    } else if (selectedItems.length === 0) {
      return 'Select items to see personalized recommendations here!';
    } else {
      return 'Great choices! Add more accessories to complete your setup.';
    }
  };

  return (
    <SidebarContainer>
      <h2>Selected Items</h2>
      {selectedItems.length === 0 ? (
        <p>No items selected.</p>
      ) : (
        selectedItems.map((item) => (
          <Item key={item.id}>
            <span>{item.Name}</span>
            <span>{item.price}</span>
            <RemoveButton onClick={() => removeItem(item.id)}>Remove</RemoveButton>
          </Item>
        ))
      )}
      <TotalPrice>Total: ${totalPrice.toFixed(2)}</TotalPrice>

      <Recommendation>{getRecommendations()}</Recommendation>

      {selectedItems.length > 0 && (
        <CheckoutButton onClick={onCheckout}>Proceed to Checkout</CheckoutButton>
      )}
    </SidebarContainer>
  );
};

export default SelectedSidebar;
